package ru.avrescue.app;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.location.*;import android.widget.*;import org.json.JSONObject;import java.util.*;
public class CreateOrderActivity extends Activity implements LocationListener{
 Spinner service,vehicle,payment;EditText address,destination,car,distance,comment;TextView geo,status,price;LocationManager lm;double lat=0,lng=0;long estimate=0;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=Ui.column(this);ScrollView s=new ScrollView(this);s.addView(l);setContentView(s);l.addView(Ui.brand(this));l.addView(Ui.text(this,"Вызвать помощь",26,true));l.addView(Ui.chip(this,"● САО • СВАО • ближайшая Московская область",true));LinearLayout c=Ui.card(this);service=spin(new String[]{"Эвакуация","Техпомощь на дороге","Запуск двигателя","Замена колеса","Подвоз топлива","Вскрытие автомобиля"});vehicle=spin(new String[]{"Легковой автомобиль","Внедорожник","Коммерческий транспорт","Мотоцикл","Грузовой автомобиль","Спецтехника"});payment=spin(new String[]{"Наличные","Онлайн — после подключения Альфа-Банка"});address=Ui.input(this,"Адрес подачи");destination=Ui.input(this,"Куда везём / место назначения");car=Ui.input(this,"Марка, модель, масса/особенности");distance=Ui.input(this,"Расстояние по маршруту, км (для теста)");comment=Ui.input(this,"Комментарий: колёса, блокировка, низкий клиренс и т.д.");geo=Ui.muted(this,"Геопозиция не определена",13);price=Ui.text(this,"Предварительная стоимость: —",20,true);status=Ui.muted(this,"",14);c.addView(Ui.muted(this,"Услуга",12));c.addView(service);c.addView(Ui.muted(this,"Автомобиль",12));c.addView(vehicle);c.addView(address);c.addView(destination);c.addView(car);c.addView(distance);c.addView(comment);c.addView(Ui.muted(this,"Оплата",12));c.addView(payment);c.addView(geo);Button gps=Ui.darkButton(this,"Определить геопозицию");gps.setOnClickListener(v->gps());c.addView(gps);Button calc=Ui.darkButton(this,"Рассчитать стоимость");calc.setOnClickListener(v->calc());c.addView(calc);c.addView(price);Button send=Ui.button(this,"Подтвердить и вызвать помощь");send.setOnClickListener(v->send());c.addView(send);c.addView(status);l.addView(c);}
 Spinner spin(String[] a){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,a));return s;}double km(){try{return Double.parseDouble(distance.getText().toString().replace(',','.'));}catch(Exception e){return 0;}}
 void calc(){status.setText("Считаем стоимость…");new Thread(()->{try{JSONObject q=new JSONObject().put("service",service.getSelectedItem().toString()).put("vehicle_type",vehicle.getSelectedItem().toString()).put("distance_km",km()).put("demand_coef",1.0).put("weather_coef",1.0);JSONObject r=ApiClient.post("/api/mobile_price_estimate.php",q);runOnUiThread(()->{if(r.optBoolean("ok")){estimate=Math.round(r.optDouble("price"));price.setText("Предварительная стоимость: "+estimate+" ₽");status.setText("Цена пересчитается сервером при оформлении.");}else status.setText(r.optString("error","Ошибка расчёта"));});}catch(Exception e){runOnUiThread(()->status.setText("Нет связи с AV Rescue"));}}).start();}
 void gps(){lm=(LocationManager)getSystemService(LOCATION_SERVICE);if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION},91);return;}try{lm.requestSingleUpdate(LocationManager.GPS_PROVIDER,this,null);}catch(Exception e){status.setText("Не удалось получить GPS");}}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==91&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)gps();}public void onLocationChanged(Location l){lat=l.getLatitude();lng=l.getLongitude();geo.setText("● Геопозиция получена");geo.setTextColor(Ui.GREEN);}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}public void onStatusChanged(String p,int st,Bundle b){}
 double[] coordinates(String value){try{if(value==null||value.trim().isEmpty())return null;List<Address> rows=new Geocoder(this,new Locale("ru","RU")).getFromLocationName(value,1);if(rows!=null&&!rows.isEmpty())return new double[]{rows.get(0).getLatitude(),rows.get(0).getLongitude()};}catch(Exception ignored){}return null;}
 void send(){if(address.getText().toString().trim().isEmpty()){status.setText("Укажите адрес подачи");return;}if(destination.getText().toString().trim().isEmpty()&&"Эвакуация".equals(service.getSelectedItem().toString())){status.setText("Укажите адрес назначения");return;}status.setText("Создаём заказ и ищем ближайшего водителя…");new Thread(()->{try{double pickupLat=lat,pickupLng=lng;double[] pickup=coordinates(address.getText().toString());if(pickup!=null){pickupLat=pickup[0];pickupLng=pickup[1];}double[] target=coordinates(destination.getText().toString());JSONObject prof=ApiClient.get("/api/mobile_dashboard.php");JSONObject u=prof.optJSONObject("profile");JSONObject q=new JSONObject().put("service",service.getSelectedItem().toString()).put("vehicle_type",vehicle.getSelectedItem().toString()).put("address",address.getText().toString()).put("destination",destination.getText().toString()).put("car",car.getText().toString()).put("comment",comment.getText().toString()).put("distance_km",km()).put("lat",pickupLat).put("lng",pickupLng).put("destination_lat",target==null?0:target[0]).put("destination_lng",target==null?0:target[1]).put("name",u==null?"":u.optString("name")).put("phone",u==null?"":u.optString("phone")).put("payment_method",payment.getSelectedItemPosition()==0?"cash":"online");JSONObject r=ApiClient.post("/api/mobile_create_order.php",q);runOnUiThread(()->{if(r.optBoolean("ok")){JSONObject o=r.optJSONObject("order");Intent in=new Intent(this,OrderDetailActivity.class);in.putExtra("order_id",o==null?"":o.optString("id"));in.putExtra("role","client");startActivity(in);finish();}else status.setText(r.optString("error","Ошибка"));});}catch(Exception e){runOnUiThread(()->status.setText("Нет связи с AV Rescue"));}}).start();}
}
